mapper.select:
SELECT season_alert_id, user_id, clothes_id, message, alert_date, status, created_at
FROM season_alerts
WHERE season_alert_id = #{seasonAlertId} AND user_id = #{userId}

mapper.update:
UPDATE season_alerts
SET status = #{status, jdbcType=VARCHAR}
WHERE season_alert_id = #{seasonAlertId}
  AND user_id = #{userId}
  AND status = 'PENDING'
  AND #{status, jdbcType=VARCHAR} IN ('DONE', 'LATER')
